PRAGMA foreign_keys = ON;

-- Authoritative maintenance snapshot supplied 2026-11-11:
-- trailer service/PM dates, trailer annual dates, and truck annual dates.
-- Blank, invalid, or future values never erase a valid production baseline.
-- Equipment identity is resolved only against one unique active matching unit.

CREATE TABLE IF NOT EXISTS maintenance_snapshot_import_receipts (
  import_batch TEXT PRIMARY KEY,
  trailer_source_rows INTEGER NOT NULL,
  trailer_matched_rows INTEGER NOT NULL,
  truck_annual_source_rows INTEGER NOT NULL,
  truck_annual_matched_rows INTEGER NOT NULL,
  unresolved_rows INTEGER NOT NULL,
  applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS maintenance_snapshot_unresolved (
  import_batch TEXT NOT NULL,
  category TEXT NOT NULL,
  source_line INTEGER NOT NULL,
  source_unit TEXT NOT NULL,
  field_name TEXT NOT NULL,
  raw_value TEXT NOT NULL DEFAULT '',
  reason TEXT NOT NULL,
  recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(import_batch,category,source_line,field_name)
);

DELETE FROM maintenance_snapshot_unresolved
WHERE import_batch='maintenance-snapshot-2026-11-11';

DROP TABLE IF EXISTS _trailer_snapshot_20261111;
CREATE TABLE _trailer_snapshot_20261111 (
  source_line INTEGER PRIMARY KEY,
  unit TEXT NOT NULL,
  service_date TEXT,
  annual_date TEXT,
  service_raw TEXT NOT NULL,
  annual_raw TEXT NOT NULL
);


DROP TABLE IF EXISTS _trailer_resolution_20261111;
CREATE TABLE _trailer_resolution_20261111 AS
WITH candidates AS (
  SELECT s.source_line,s.unit,e.id AS equipment_id
  FROM _trailer_snapshot_20261111 s
  JOIN equipment e
    ON e.active=1
   AND e.archived_at IS NULL
   AND (lower(COALESCE(e.equipment_type,''))='trailer' OR e.geotab_trailer_id IS NOT NULL)
   AND (
      upper(trim(e.unit))=upper(s.unit)
      OR upper(trim(e.unit)) LIKE upper(s.unit)||' (%'
      OR upper(trim(e.unit)) LIKE upper(s.unit)||'(%'
      OR upper(trim(e.unit))='TRL '||upper(s.unit)
      OR upper(trim(e.unit)) LIKE 'TRL '||upper(s.unit)||' (%'
      OR upper(trim(e.unit)) LIKE 'TRL '||upper(s.unit)||'(%'
      OR upper(trim(e.unit))='TRAILER '||upper(s.unit)
      OR upper(trim(e.unit)) LIKE 'TRAILER '||upper(s.unit)||' (%'
      OR upper(trim(e.unit)) LIKE 'TRAILER '||upper(s.unit)||'(%'
   )
),
grouped AS (
  SELECT s.source_line,s.unit,
         COUNT(c.equipment_id) AS candidate_count,
         CASE WHEN COUNT(c.equipment_id)=1 THEN MAX(c.equipment_id) END AS equipment_id
  FROM _trailer_snapshot_20261111 s
  LEFT JOIN candidates c ON c.source_line=s.source_line
  GROUP BY s.source_line,s.unit
)
SELECT * FROM grouped;

INSERT OR REPLACE INTO maintenance_snapshot_unresolved
  (import_batch,category,source_line,source_unit,field_name,raw_value,reason)
SELECT 'maintenance-snapshot-2026-11-11','trailer',s.source_line,s.unit,'equipment_match','',
       CASE WHEN r.candidate_count=0
            THEN 'No unique active trailer equipment match.'
            ELSE 'Multiple active trailer equipment matches.' END
FROM _trailer_snapshot_20261111 s
JOIN _trailer_resolution_20261111 r USING(source_line)
WHERE (s.service_date IS NOT NULL OR s.annual_date IS NOT NULL)
  AND r.equipment_id IS NULL;

SELECT r.equipment_id,s.service_date,s.annual_date,CURRENT_TIMESTAMP
FROM _trailer_snapshot_20261111 s
JOIN _trailer_resolution_20261111 r USING(source_line)
WHERE r.equipment_id IS NOT NULL
  AND (s.service_date IS NOT NULL OR s.annual_date IS NOT NULL)
ON CONFLICT(equipment_id) DO UPDATE SET
  service_date=COALESCE(excluded.service_date,pm_status.service_date),
  annual_date=COALESCE(excluded.annual_date,pm_status.annual_date),
  updated_at=CURRENT_TIMESTAMP;

UPDATE equipment AS e
SET service_date=COALESCE((
      SELECT s.service_date
      FROM _trailer_snapshot_20261111 s
      JOIN _trailer_resolution_20261111 r USING(source_line)
      WHERE r.equipment_id=e.id
    ),e.service_date),
    annual_date=COALESCE((
      SELECT s.annual_date
      FROM _trailer_snapshot_20261111 s
      JOIN _trailer_resolution_20261111 r USING(source_line)
      WHERE r.equipment_id=e.id
    ),e.annual_date),
    updated_at=CURRENT_TIMESTAMP
WHERE e.id IN (
  SELECT equipment_id FROM _trailer_resolution_20261111 WHERE equipment_id IS NOT NULL
);

DROP TABLE IF EXISTS _truck_annual_snapshot_20261111;
CREATE TABLE _truck_annual_snapshot_20261111 (
  source_line INTEGER PRIMARY KEY,
  unit TEXT NOT NULL,
  annual_date TEXT,
  raw_value TEXT NOT NULL,
  value_status TEXT NOT NULL
);


INSERT OR REPLACE INTO maintenance_snapshot_unresolved
  (import_batch,category,source_line,source_unit,field_name,raw_value,reason)
SELECT 'maintenance-snapshot-2026-11-11','truck-annual',source_line,unit,'annual_date',raw_value,
       CASE value_status
         WHEN 'future' THEN 'Future annual date was not applied.'
         ELSE 'Invalid annual date was not applied.'
       END
FROM _truck_annual_snapshot_20261111
WHERE value_status IN ('future','invalid');

DROP TABLE IF EXISTS _truck_annual_resolution_20261111;
CREATE TABLE _truck_annual_resolution_20261111 AS
WITH candidates AS (
  SELECT s.source_line,s.unit,e.id AS equipment_id,
         CASE
           WHEN upper(trim(e.unit))=upper(trim(s.unit)) THEN 1
           WHEN upper(trim(s.unit))='FORD TRANSIT'
             AND upper(trim(e.unit)) IN ('FORD TRANSIT','FORD TRANSIT VAN') THEN 1
           WHEN substr(trim(s.unit),1,1) BETWEEN '0' AND '9'
             AND trim(CASE WHEN instr(e.unit,'(')>0
                           THEN substr(e.unit,1,instr(e.unit,'(')-1)
                           ELSE e.unit END)=trim(s.unit) THEN 2
           ELSE 99
         END AS score
  FROM _truck_annual_snapshot_20261111 s
  JOIN equipment e
    ON e.active=1
   AND e.archived_at IS NULL
   AND lower(COALESCE(e.equipment_type,'truck'))<>'trailer'
   AND e.geotab_trailer_id IS NULL
  WHERE s.annual_date IS NOT NULL
    AND (
      upper(trim(e.unit))=upper(trim(s.unit))
      OR (upper(trim(s.unit))='FORD TRANSIT'
          AND upper(trim(e.unit)) IN ('FORD TRANSIT','FORD TRANSIT VAN'))
      OR (
        substr(trim(s.unit),1,1) BETWEEN '0' AND '9'
        AND trim(CASE WHEN instr(e.unit,'(')>0
                      THEN substr(e.unit,1,instr(e.unit,'(')-1)
                      ELSE e.unit END)=trim(s.unit)
      )
    )
),
best AS (
  SELECT source_line,MIN(score) AS best_score
  FROM candidates
  GROUP BY source_line
),
grouped AS (
  SELECT s.source_line,s.unit,
         COUNT(c.equipment_id) AS candidate_count,
         CASE WHEN COUNT(c.equipment_id)=1 THEN MAX(c.equipment_id) END AS equipment_id
  FROM _truck_annual_snapshot_20261111 s
  LEFT JOIN best b ON b.source_line=s.source_line
  LEFT JOIN candidates c ON c.source_line=s.source_line AND c.score=b.best_score
  GROUP BY s.source_line,s.unit
)
SELECT * FROM grouped;

INSERT OR REPLACE INTO maintenance_snapshot_unresolved
  (import_batch,category,source_line,source_unit,field_name,raw_value,reason)
SELECT 'maintenance-snapshot-2026-11-11','truck-annual',s.source_line,s.unit,'equipment_match',s.raw_value,
       CASE WHEN r.candidate_count=0
            THEN 'No unique active non-trailer equipment match.'
            ELSE 'Multiple active non-trailer equipment matches.' END
FROM _truck_annual_snapshot_20261111 s
JOIN _truck_annual_resolution_20261111 r USING(source_line)
WHERE s.annual_date IS NOT NULL
  AND r.equipment_id IS NULL;

INSERT OR IGNORE INTO equipment_annual_settings
  (equipment_id,interval_days,active,updated_at)
SELECT r.equipment_id,365,1,CURRENT_TIMESTAMP
FROM _truck_annual_snapshot_20261111 s
JOIN _truck_annual_resolution_20261111 r USING(source_line)
WHERE s.annual_date IS NOT NULL
  AND r.equipment_id IS NOT NULL;

SELECT r.equipment_id,s.annual_date,CURRENT_TIMESTAMP
FROM _truck_annual_snapshot_20261111 s
JOIN _truck_annual_resolution_20261111 r USING(source_line)
WHERE s.annual_date IS NOT NULL
  AND r.equipment_id IS NOT NULL
ON CONFLICT(equipment_id) DO UPDATE SET
  annual_date=excluded.annual_date,
  updated_at=CURRENT_TIMESTAMP;

UPDATE equipment AS e
SET annual_date=(
      SELECT s.annual_date
      FROM _truck_annual_snapshot_20261111 s
      JOIN _truck_annual_resolution_20261111 r USING(source_line)
      WHERE r.equipment_id=e.id
        AND s.annual_date IS NOT NULL
    ),
    updated_at=CURRENT_TIMESTAMP
WHERE e.id IN (
  SELECT r.equipment_id
  FROM _truck_annual_snapshot_20261111 s
  JOIN _truck_annual_resolution_20261111 r USING(source_line)
  WHERE r.equipment_id IS NOT NULL
    AND s.annual_date IS NOT NULL
);

INSERT OR REPLACE INTO maintenance_snapshot_import_receipts
  (import_batch,trailer_source_rows,trailer_matched_rows,
   truck_annual_source_rows,truck_annual_matched_rows,unresolved_rows,applied_at)
SELECT 'maintenance-snapshot-2026-11-11',
       (SELECT COUNT(*) FROM _trailer_snapshot_20261111),
       (SELECT COUNT(*) FROM _trailer_resolution_20261111 WHERE equipment_id IS NOT NULL),
       (SELECT COUNT(*) FROM _truck_annual_snapshot_20261111),
       (SELECT COUNT(*)
        FROM _truck_annual_resolution_20261111 r
        JOIN _truck_annual_snapshot_20261111 s USING(source_line)
        WHERE r.equipment_id IS NOT NULL AND s.annual_date IS NOT NULL),
       (SELECT COUNT(*) FROM maintenance_snapshot_unresolved
        WHERE import_batch='maintenance-snapshot-2026-11-11'),
       CURRENT_TIMESTAMP;

DROP TABLE _truck_annual_resolution_20261111;
DROP TABLE _truck_annual_snapshot_20261111;
DROP TABLE _trailer_resolution_20261111;
DROP TABLE _trailer_snapshot_20261111;
